script:
const phanHe = ctx.val('phan_he', 'maintenance').trim().toLowerCase() || 'maintenance';
const targetUrl = `https://tasks.zuizui.io/${phanHe}/dashboard`;

await step('Mở màn hình Báo cáo Tổng Quan', async () => {
  if (!page.url().includes(`/${phanHe}/dashboard`)) {
    await page.goto(targetUrl, { waitUntil: 'domcontentloaded' });
  }
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  await page.getByText('Phiếu chưa hoàn tất', { exact: true }).first().waitFor({ timeout: 20000 });
});

await step('Kiểm tra bộ lọc Phân loại phiếu và Vùng miền', async () => {
  const catFilter = page.getByText('Chọn Phân loại phiếu').first();
  if (await catFilter.isVisible().catch(() => false)) {
    await catFilter.click();
    const selectAll = page.getByText('Chọn tất cả').first();
    if (await selectAll.isVisible().catch(() => false)) await selectAll.click();
    await page.keyboard.press('Escape').catch(() => {});
  }
  const regionFilter = page.getByText('Chọn vùng miền').first();
  if (await regionFilter.isVisible().catch(() => false)) {
    await regionFilter.click();
    const vung = ctx.val('vung_mien', 'Cả nước');
    const opt = page.getByText(vung, { exact: true }).first();
    if (await opt.isVisible().catch(() => false)) await opt.click();
    await page.keyboard.press('Escape').catch(() => {});
  }
});

await step('Kiểm tra các thẻ KPI và biểu đồ trên Tổng Quan', async () => {
  const txt = await page.locator('body').innerText();
  for (const label of [
    'Phiếu chưa hoàn tất',
    'Không đạt SLAs',
    'Đã hoàn tất hôm nay',
    'Đã hoàn tất tuần này'
  ]) {
    assert(txt.includes(label), 'Thiếu thẻ KPI trên Tổng Quan: ' + label);
  }
  const chartBtns = page.locator('.wrapp-box-chart-maintenance-btn-view-icon > div:nth-child(2)');
  if (await chartBtns.count()) {
    await chartBtns.first().click();
    await page.waitForTimeout(400);
    await page.locator('.wrapp-box-chart-maintenance-btn-view-icon > div').first().click();
  }
  ctx.log('Báo cáo Tổng Quan hiển thị đầy đủ KPI và biểu đồ.');
});
